L000544	\section{Classical statistical mechanics and the Peierls condition}\label{app:cla}
L000545	
L000546	This appendix will introduce the set of classical models of interest in our paper and review important known results about them.
L000547	
L000548	\subsection{Peierls condition}
L000549	
L000550	\begin{defn}[Configuration space]\label{def:Omega}
L000551	    Let $\Lambda$ denote the vertex set of a graph $G$ with $N=|\Lambda|$ a finite number. Place one $r$-dimensional bit at each vertex $i\in \Lambda$.  The configuration space $\Omega$ corresponds to the set of all ``bitstrings" $\bz$: $\Omega=\mathbb{Z}_r^\Lambda$. The Hamming distance $\mathrm{Ham}(\bz,\bz')$ is the number of vertices where $\bz,\bz'$ differ, and \begin{equation}
L000552	        \mathrm{Ham}(W,W'):=\min_{\bz \in W,\bz'\in W'} \mathrm{Ham}(\bz,\bz')
L000553	    \end{equation}
L000554	    for any $W,W'\subset \Omega$.
L000555	    For each subset $A\subset \Lambda$, define its edge boundary $\partial A$ as the set of edges in $G$ that connects one vertex in $A$ with one outside. Denote $\partial A$ by the set of vertices in $A$ sharing some edge in $\partial A$.
L000556	\end{defn}
L000557	
L000558	
L000559	
L000560	
L000561	
L000562	
L000563	
L000564	
L000565	
L000566	
L000567	
L000568	
L000569	
L000570	
L000571	
L000572	
L000573	
L000574	
L000575	
L000576	
L000577	
L000578	\begin{defn}[Bottleneck and Peierls condition]\label{def:peierls}
L000579	    We say $(\{W_k,\Phi_k,\mathcal{B}_k\}^K_{k=1},R)$ is a bottleneck structure if the following holds:
L000580	    \begin{enumerate}
L000581	        \item $W_k,\Phi_k\subset \Omega,R\ge 1$. Consider the ``Hamming graph" with vertices $\Omega$ and edges connecting $\bz,\bz'$ if $\mathrm{Ham}(\bz,\bz')\le R$. $\{W_k\}^K_{k=1}$ is pairwise disconnected, and $\Phi_k\subset \Omega\setminus W_k$ includes all vertices outside $W_k$ but connected to $W_k$ on this Hamming graph. We call each $W_k$ a well and $\Phi_k$ its bottleneck. Note that $\Phi_k$ may contain vertices disconnected to $W_k$, and may overlap with other $\Phi_{k'},W_{k'}$.
L000582	        \item $\mathcal{B}_k$ is a set where each bottleneck indicator $B\in \mathcal{B}_k$ is a function $B:\Omega \rightarrow \lbrace 0,1\rbrace$. For any $\bz \in \Phi_k$, there exists at least one $B$ with $B(\bz)=1$.
L000583	    \end{enumerate}
L000584	
L000585	
L000586	
L000587	
L000588	    We say Hamiltonian $H_0$ satisfies $(\Delta,\theta,L,R)$-Peierls condition (PC) for the bottleneck structure above, if the following conditions hold: \begin{enumerate}
L000589	        \item $\forall k$ and $\forall B\in \mathcal{B}_k$, there is an injective map $M_B:\Phi_k\rightarrow W_k\sqcup \Phi_k$ such that $\forall \bz\in \Phi_k$ with $B(\bz)=1$, \begin{equation}\label{eq:Mz>Delta L}
L000590	        H_0(\bz)\ge  \Delta \cdot L  + H_0(M_B\cdot \bz).
L000591	    \end{equation}
L000592	    $M_B$ may depend on $k$ implicitly.
L000593	    \item The total number of different bottleneck indicators $B\in\mathcal{B}_k$ is bounded: $\forall k$, \begin{equation}\label{eq:B<thetaL}
L000594	        |\mathcal{B}_k|\le \ee^{\theta L}.
L000595	    \end{equation}
L000596	    \end{enumerate}
L000597	
L000598	
L000599	\end{defn}
L000600	
L000601	Note that we assume a weaker version of Peierls condition comparing to the standard one (see e.g. Section 7.2 in \cite{lattice_book17}).  Here we only need to constrain the energies of states in the bottleneck sets $\Phi_k$.  For the example of studying the 2d Ising ferromagnetic phase, we only need to worry about the energy of states with system-size spanning domain walls of size $L \sim \sqrt{N}$.  As a result, we will see that $H_0$ can be gapless while still satisfying \eqref{eq:Mz>Delta L}.   An explicit example is the random bond Ising model, discussed in Appendix \ref{sec:rand_bond}.
L000602	
L000603	
L000604	\subsection{Peierls argument}
L000605	
L000606	\begin{defn}[Thermal ensemble/Gibbs state]
L000607	    The thermal ensemble/Gibbs state at inverse temperature $\beta$ is a probability distribution on $\Omega$ defined as follows: \begin{equation}
L000608	        \mathbb{P}_\beta(\bz) := \frac{\mathrm{e}^{-\beta H_0(\bz)}}{\mathcal{Z}(\beta)}
L000609	    \end{equation}
L000610	    where the partition function $Z$ and free energy $F(\beta)$ are defined as \begin{equation}\label{eq:partitionfunc=}
L000611	        \mathcal{Z}(\beta) := \mathrm{e}^{-\beta F(\beta)} := \sum_{\bz\in\Omega }\mathrm{e}^{-\beta H_0(\bz)}.
L000612	    \end{equation}
L000613	    Given a state subspace $W\subset \Omega$, we also define a restricted Gibbs state\footnote{The notion of restricted Gibbs state is sometimes known as ``pure states'' in spin glass literature; however, we do not use this terminology because it is easily confused with the notion of pure states in quantum mechanics.} as a probability distribution on $W$ \begin{equation}
L000614	        \mathbb{P}^W_\beta(\bz) := \frac{\mathrm{e}^{-\beta H_0(\bz)}}{\mathcal{Z}^W(\beta)}\mathbb{I}(\bz\in W),\where \mathcal{Z}^W(\beta) := \sum_{\bz\in W }\mathrm{e}^{-\beta H_0(\bz)}.
L000615	    \end{equation}
L000616	    Here $\mathbb{I}(\cdot)$ returns $1$ if $\cdot$ is true and $0$ if it is false.
L000617	\end{defn}
L000618	
L000619	
L000620	
L000621	\begin{prop}[Peierls argument] \label{prop:classicalpeierls}
L000622	    If $H_0$ obeys a $(\Delta,\theta,L,R)$-Peierls condition (PC), then for \begin{equation}
L000623	        \beta  >\frac{\Delta}{\theta} \label{eq:peierlsbeta}
L000624	    \end{equation}
L000625	    the Gibbs state has exponentially small support in the bottlenecks compared to the wells: $\forall k$, \begin{equation}
L000626	        \mathbb{P}_\beta(\Phi_k) \le \frac{\ee^{-(\beta\Delta-\theta)L}}{1-\ee^{-(\beta\Delta-\theta)L}}\mathbb{P}_\beta(W_k) . \label{eq:exponentiallysmallsupport}
L000627	    \end{equation}
L000628	\end{prop}
L000629	\begin{proof}
L000630	This follows from a direct calculation:
L000631	\begin{align}
L000632	    \sum_{\bz\in \Phi_k}\ee^{-\beta H_0(\bz)} &\le \sum_{B\in \mathcal{B}_k} \sum_{\bz\in \Phi_k:B(\bz)=1} \ee^{-\beta H_0(\bz)} \nonumber\\
L000633	    &\le \sum_{B\in \mathcal{B}_k} \sum_{\bz\in\Phi_k:B(\bz)=1} \ee^{-\beta \mlr{\Delta L+ H_0(M_B\cdot \bz)} } \mytag{\text{Using \eqref{eq:Mz>Delta L}}} \\
L000634	    &\le \ee^{-\beta \Delta L}\sum_{B\in \mathcal{B}_k} \sum_{\bz':\bz'=M_B\cdot \bz \text{ for some }\bz\in \Phi_k} \ee^{-\beta  H_0(\bz')}\mytag{M_B\text{ is injective}} \\
L000635	    &\le \ee^{-\beta \Delta L}|\mathcal{B}_k| \sum_{\bz'\in W_k\sqcup \Phi_k} \ee^{-\beta  H_0(\bz')} \mytag{M_B\text{ maps onto }W_k} \\
L000636	    &\le \ee^{-(\beta \Delta -\theta) L}\sum_{\bz'\in W_k\sqcup \Phi_k} \ee^{-\beta  H_0(\bz')} \mytag{\text{Using \eqref{eq:B<thetaL}}}
L000637	\end{align}
L000638	Dividing both sides by $\mathcal{Z}(\beta)$ yields \begin{equation}
L000639	    \mathbb{P}_\beta(\Phi_k) \le \ee^{-(\beta\Delta-\theta)L}\mathbb{P}_\beta(W_k\sqcup \Phi_k) = \ee^{-(\beta\Delta-\theta)L}\mlr{\mathbb{P}_\beta(\Phi_k)+\mathbb{P}_\beta(W_k)},
L000640	\end{equation}
L000641	from which we can easily obtain \eqref{eq:exponentiallysmallsupport}.
L000642	\end{proof}
L000643	
L000644	The critical point about building a bottleneck is that when we introduce ``dynamics" -- either via a Gibbs sampler in classical statistical physics, or via quantum fluctuations when we turn to quantum models -- the configuration space $\Omega$ becomes disconnected once the bottlenecks $\Phi_k$ are removed.
L000645	At the same time, the bottleneck is very unlikely to be occupied in thermal equilibrium.  For classical Markov chain dynamics, this is enough to show, by the following Proposition, that a Gibbs sampler will be trapped in only one well $W_k$ for a very long time \cite{levin_markovchains}, as was illustrated in Figure \ref{fig:maintext}.  The main result of this paper is that a similar result holds in quantum systems -- we will build almost eigenstates of a many-body system with a bottleneck and prove that the system is trapped on one side of the bottleneck for extremely long times.   For convenience, here we review the proof of a bottleneck bound in classical Markov chains:
L000646	
L000647	\begin{prop}\label{prop:markov}
L000648	    Consider a Markov chain transition matrix $T$ with entries obeying detailed balance \begin{equation}\label{eq:detail_balance}
L000649	        T_{\bz'\leftarrow \bz}\mathbb{P}_\beta(\bz) = T_{\bz\leftarrow \bz'}\mathbb{P}_\beta(\bz'),\quad \forall \bz,\bz'
L000650	    \end{equation}
L000651	    and locality \begin{equation}\label{eq:local_transition}
L000652	        \mathrm{Ham}(\bz,\bz')\ge R \quad \Rightarrow \quad T_{\bz'\leftarrow \bz}=0.
L000653	    \end{equation}
L000654	    For any $W=W_k$ in \eqref{eq:exponentiallysmallsupport}, the restricted Gibbs state in that set is almost-steady: \begin{equation}
L000655	        \norm{T\mathbb{P}^W_\beta - \mathbb{P}^W_\beta}_1:=\sum_{\bz\in \Omega}\abs{\lr{T\mathbb{P}^W_\beta}(\bz) - \mathbb{P}^W_\beta(\bz)} \le \frac{2\ee^{-(\beta\Delta-\theta)L}}{1-\ee^{-(\beta\Delta-\theta)L}}.
L000656	    \end{equation}
L000657	\end{prop}
L000658	
L000659	\begin{proof}
L000660	    Due to detailed balance \eqref{eq:detail_balance}, probability distribution $T\mathbb{P}^W_\beta$ differs from $\mathbb{P}^W_\beta$ only by moving mass from some $\bz\in W$ to some other $\bz'\notin W$, which is contained in $\Phi:=\Phi_k$ from \eqref{eq:local_transition}: \begin{align}
L000661	        \norm{T\mathbb{P}^W_\beta - \mathbb{P}^W_\beta}_1&= \sum_{\mathbf{z}\in \Phi, \mathbf{z}^\prime \in W} T_{\mathbf{z}\leftarrow \mathbf{z}^\prime } \mathbb{P}^W_\beta(\mathbf{z}^\prime) + \sum_{\mathbf{z}\in W, \mathbf{z}^\prime} \left|T_{\mathbf{z}\leftarrow \mathbf{z}^\prime}\mathbb{P}^W_\beta(\mathbf{z}^\prime) -\mathbb{P}^W_\beta(\mathbf{z}^)\right|  \nonumber\\
L000662	        &= \sum_{\mathbf{z}\in \Phi, \mathbf{z}^\prime \in W} T_{\mathbf{z}\leftarrow \mathbf{z}^\prime } \mathbb{P}^W_\beta(\mathbf{z}^\prime) + \sum_{\mathbf{z}\in W, \mathbf{z}^\prime} \left|\left(T_{\mathbf{z}^\prime\leftarrow \mathbf{z}}-1\right)\mathbb{P}^W_\beta(\mathbf{z})\right| \mytag{\text{Detailed balance}} \nonumber\\
L000663	        &=2\sum_{\bz\in W,\bz'\in \Phi} T_{\bz'\leftarrow \bz}\mathbb{P}^W_\beta(\bz) \nonumber\\
L000664	        &= 2\frac{\mathcal{Z}_\beta}{\mathcal{Z}_\beta^W}\sum_{\bz\in W,\bz'\in \Phi} T_{\bz'\leftarrow \bz}\mathbb{P}_\beta(\bz) \nonumber\\
L000665	        &=2\frac{\mathcal{Z}_\beta}{\mathcal{Z}_\beta^W}\sum_{\bz\in W,\bz'\in \Phi} T_{\bz\leftarrow \bz'}\mathbb{P}_\beta(\bz') \mytag{\text{Detailed balance}} \\
L000666	        &\le 2\frac{\mathcal{Z}_\beta}{\mathcal{Z}_\beta^W}\sum_{\bz'\in \Phi} \mathbb{P}_\beta(\bz') \mytag{\sum_{\bz}T_{\bz\leftarrow \bz'}\le 1} \\
L000667	        &\le 2\frac{\mathcal{Z}_\beta}{\mathcal{Z}_\beta^W}\ee^{-(\beta\Delta-\theta)L}\mathbb{P}_\beta(W_k) = \frac{2\ee^{-(\beta\Delta-\theta)L}}{1-\ee^{-(\beta\Delta-\theta)L}},
L000668	    \end{align}
L000669	    where the last step uses \eqref{eq:exponentiallysmallsupport}.
L000670	\end{proof}
