L000950	\subsection{Almost eigenstates}
L000951	
L000952	
L000953	
L000954	
L000955	Before we begin to state our main results about the implications of QPC on the low-energy eigenstates of a many-body Hamiltonian, we will introduce the simple concept of almost eigenstates.\footnote{This object may go by the names ``approximate eigenstate" or ``pseudoeigenstate" in other literature.}
L000956	
L000957	\begin{defn}[Almost eigenstate]
L000958	    $|\psi\rangle$ is an $\delta$-almost eigenstate of Hamiltonian $H$ with eigenvalue $E$ if \begin{equation}
L000959	        \left\lVert (H-E) |\psi\rangle \right\rVert \le \delta \lVert |\psi\rangle \rVert. \label{eq:almosteigenstate}
L000960	    \end{equation}
L000961	    Here and below, $\lVert |\psi\rangle \rVert = \sqrt{\langle \psi|\psi\rangle}$.
L000962	\end{defn}
L000963	
L000964	$\kpsi$ becomes an exact eigenstate when $\delta=0$. For small $\delta$, $\kpsi$ approximates an eigenstate in dynamics, i.e. it is almost stationary when evolved by $H$.
L000965	
L000966	
L000967	
L000968	\begin{prop}
L000969	    If $|\psi\rangle$ is a $\delta$-almost eigenstate of $H$ with eigenvalue $E$, and $\langle \psi|\psi\rangle = 1$, then for any operator $A$ with Heisenberg evolution $A(t)=\ee^{\ii t H}A\ee^{-\ii t H}$,  \begin{equation}
L000970	        |\langle \psi | A(t)|\psi\rangle - \langle \psi|A|\psi\rangle | \le 2\lVert A\rVert \delta t. \label{eq:dynamicalstabilityobservable}
L000971	    \end{equation}
L000972	\end{prop}
L000973	\begin{proof}
L000974	Using the Duhamel identity we may write \begin{equation}
L000975	        \mathrm{e}^{-\mathrm{i}Ht}|\psi\rangle =  \left[ |\psi\rangle + \int_0^t\mathrm{d}s \; \mathrm{e}^{-\mathrm{i}Hs}(H-E)\mathrm{e}^{\mathrm{i}Es}|\psi\rangle \right]\mathrm{e}^{-\mathrm{i}Et} =: \left[|\psi\rangle + |\phi\rangle  \right]\mathrm{e}^{-\mathrm{i}Et}.
L000976	    \end{equation}
L000977	    Thus \begin{equation}
L000978	        \langle \psi(t)|A|\psi(t)\rangle  -\langle \psi|A|\psi\rangle =  \langle \phi|A|\psi\rangle + \langle \psi|A|\phi\rangle + \langle \phi|A|\phi\rangle \le \lVert |\phi\rangle \rVert_2 \lVert A\rVert \lVert\lr{\norm{\kpsi}+\norm{\kpsi+\ket{\phi}}}  \le 2\lVert A\rVert \lVert |\phi\rangle \rVert_2.
L000979	    \end{equation}
L000980	    Here and below, $\lVert A\rVert$ denotes the operator norm when acting on an oeprator rather than a vector.  By the triangle inequality and the fact that a unitary operator has norm $\lVert \mathrm{e}^{-\mathrm{i}(H-E)s}\rVert = 1$,  \begin{equation}
L000981	        \lVert |\phi\rangle \rVert_2 \le \int_0^t \mathrm{d}s \left\lVert  \mathrm{e}^{-\mathrm{i}Hs}(H-E)\mathrm{e}^{\mathrm{i}Es}|\psi\rangle\right\rVert_2 \le t\lVert (H-E)|\psi\rangle \rVert_2. \label{eq:triangleinequalityphi}
L000982	    \end{equation}
L000983	    Combining \eqref{eq:almosteigenstate} and \eqref{eq:triangleinequalityphi} we obtain \eqref{eq:dynamicalstabilityobservable}.
L000984	\end{proof}
