L000989	    \caption{Illustration of a quantum bottleneck structure. Here $\mathcal{B}_{\rm out}$ is not required for the basic Definition \ref{def:q_bottle}, but appears in the global version Definition \ref{def:QPC_global}. }
L000990	    \label{fig:bottleneck}
