L000993	\subsection{Stability of ground states}
L000994	Now we turn to tackle the main physics problem of interest in this paper:  the structure of low-energy states in many-body quantum Hamiltonians subject to QPC.
L000995	\begin{defn}[Perturbed Hamiltonian]\label{def:perturbH}
L000996	    We study a quantum many-body system with Hamiltonian \begin{equation}
L000997	        H = H_0+ V
L000998	    \end{equation}
L000999	    where $H_0$ commutes with all checks: $[H_0,C]=0$, and perturbation $V$ satisfies: \begin{enumerate}
L001000	        \item It is $q$-local with constant $q$, in the sense that $V=\sum_{F\subset \Lambda} V_F$ where $V_F$ is supported on $F$, and all $|F|\le q$.
L001001	        \item It has local strength \begin{equation}\label{eq:eps=V}
L001002	        \epsilon=\max_{i\in \Lambda} \sum_{F\ni i}\norm{V_F}.
L001003	    \end{equation}
L001004	    \end{enumerate}
L001005	\end{defn}
L001006	
L001007	In the literature, it is well-established \cite{michalakis2013stability} that so long as $H_0$ is short-range and gapped with a local topological order condition, for sufficiently small $\epsilon$ the Hamiltonian $H$ is also gapped and there is a quasilocal unitary that rotates the ground state subspace of $H_0$ to that of $H$. Although such stability results are expected to hold beyond gapped systems, previous approaches \cite{yarotsky2006ground,topo_Hastings,bravyi2011short,frustration_free_22,yin_ldpc,ldpc_roeck,michalakis2013stability} seem to rely fundamentally on the gap $\Delta$, which effectively block-diagonalize the two subspaces separated by the gap using small $\sim \epsilon/\Delta\ll 1$ local rotations.
L001008	
L001009	The purpose of this paper is to prove weaker a notion of stability for an $H$ which obeys Definition \ref{def:QPC}.  Crucially, however, Definition \ref{def:QPC} allows for $H_0$ to be \emph{long-range}, \emph{gapless} and even \emph{frustrated}.  As far as we know, there is no quantum theory of stable phases of matter in the presence of these complications; though see \cite{yin_ldpc,ldpc_roeck} for work on the stability of codes without spatial locality.  Our main result, Theorem \ref{thm:mainstable}, thus represents a first step towards a more general classification of phases of matter.
L001010	
L001011	\begin{thm}\label{thm:mainstable}
L001012	    Let $H$ be constructed as in Definition \ref{def:perturbH}.  If $H$ satisfies $(\Delta,\theta,L,q)$-QPC and \begin{equation}\label{eq:eps<Delta}
L001013	        \epsilon =\zeta \cdot \frac{\Delta}{3g} \ee^{-\frac{5}{2}qg\theta} <\frac{\Delta}{3g}\times \min\mlr{\frac{1}{\sqrt{2}}, \ee^{-\frac{5}{2}qg\theta} },
L001014	    \end{equation}
L001015	    with $0<\zeta <1$,
L001016	    then for any $k$ and arbitrary eigenstate $|\psi\rangle=P_k\kpsi$ of the restricted Hamiltonian $P_kHP_k$: \begin{equation}\label{eq:Hpsi=Epsi}
L001017	P_kH P_k|\psi\rangle = E|\psi\rangle,
L001018	    \end{equation}
L001019	    with \begin{equation}\label{eq:E_close_GS}
L001020	        E \le H_{k,\mathrm{min}} + \frac{1}{2}\Delta L
L001021	    \end{equation}
L001022	    where \begin{equation}
L001023	        H_{k,\mathrm{min}} := \min_{|\psi\rangle = P_k|\psi\rangle} \frac{\langle \psi|P_kHP_k|\psi\rangle}{\langle \psi|\psi\rangle},
L001024	    \end{equation}
L001025	    it has exponentially small support in bottleneck \begin{equation}\label{eq:Phik<expL}
L001026	        \norm{\Phi_k\kpsi}^2\le \exp\left[ -L \cdot   \frac{2}{5qg}\log \frac{1}{\zeta} \right] .
L001027	    \end{equation}
L001028	    Furthermore, $\kpsi$ is an $\delta$-almost eigenstate of $H$ with \begin{equation}\label{eq:provealmost}
L001029	        \delta=\norm{H}\exp\left[ -L \cdot   \frac{1}{5qg}\log \frac{1}{\zeta} \right] \le \exp\left[ -L \cdot   \frac{1}{6qg}\log \frac{1}{\zeta} \right],
L001030	    \end{equation}
L001031	    if $\norm{H}=\poly{L}$ and $L$ is sufficiently large comparing to constants $q,g,\zeta$.
L001032	\end{thm}
L001033	
L001034	We again emphasize that we need QPC for the perturbed Hamiltonian $H$, instead of the unperturbed one. This makes sense because e.g. symmetric $H_0$ should be stable only against symmetric perturbation $V$; asymmetric $V$ will violate QPC of $H$ (Example \ref{exam:symmetric_violate}).
L001035	
L001036	\begin{proof}
L001037	We can apply the union bound to the classical probabilities $\langle \psi|B|\psi\rangle$ to find the system in each bottleneck $B\in\mathcal{B}_k$ to obtain:  \begin{equation}\label{eq:bn<sumB}
L001038	    \langle \psi|\Phi_k|\psi\rangle \le \sum_{B\in \mathcal{B}_k} \langle \psi|B|\psi\rangle \le \mathrm{e}^{\theta L}\cdot \max_{B\in\mathcal{B}_k}\langle \psi|B|\psi\rangle =  \mathrm{e}^{\theta L}\cdot \max_{B\in\mathcal{B}_k}\norm{B\kpsi}^2.
L001039	\end{equation}
L001040	We then focus on one $B$ and bound $\norm{B\kpsi}^2$.
L001041	
L001042	Following \cite{MBL_LDPC24}, we write \begin{equation}\label{eq:psi=psin}
L001043	    \kpsi = \sum_{n=1}^{n_*+1} A_n \ket{\psi_n}
L001044	\end{equation}
L001045	where $A_n\ge 0$, and $\ket{\psi_n}$ is normalized and supported in different eigensubspaces of $E_B$. More precisely, $\ket{\psi_{1}}$ is supported in subspace $E_B=L_B$, $\ket{\psi_2}$ is supported in $E_B=L_B-1,\cdots,L_B-qg$, $\ket{\psi_3}$ is supported in $E_B=L_B-qg-1,\cdots,L_B-2qg$, $\cdots$. By construction, each $\ket{\psi_n}$ is contained in subspace $P_k$. We choose \begin{equation}\label{eq:nstar=}
L001046	    n_*= \floor{ \frac{L}{5qg} } +1 \ge \frac{L}{5qg},
L001047	\end{equation}
L001048	so that all $\ket{\psi_n}$ with $n\le n_*$ are supported in range $E_B\ge\frac{4}{5}L_B$; the remaining part of $\kpsi$ corresponds to $\ket{\psi_{n_*+1}}$. Each $\ket{\psi_n}\propto \widetilde{Q}_n \ket{\psi}$ for some projector $\widetilde{Q}_n$, which is a sum over projectors $Q_{B,n'}$ with $n'$ in the corresponding $E_B$ window; we remind the reader that $[Q_{B,n'},P_k]=0$ from the assumptions in Definitions \ref{def:q_bottle} and \ref{def:perturbH}, which is why we may safely perform this decomposition.
L001049	
L001050	Because each qudit is involved in at most $g$ checks and $V$ is $q$-local, it can change $E_B$ by at most $qg$. Furthermore, $H_0$ commutes with $E_B$, so expanding eigenstate equation \eqref{eq:Hpsi=Epsi} using \eqref{eq:psi=psin} yields \begin{equation} \label{eq:H=E_expanded}
L001051	    \widetilde{Q}_n A_n P_k(H-E)\ket{\psi_n} = -\widetilde{Q}_n A_{n+1} P_k V \ket{\psi_{n+1}} - \widetilde{Q}_n A_{n-1}P_kV\ket{\psi_{n-1}}
