L001058	    A_n \frac{\Delta}{2}L_B \le A_{n+1} v_n + A_{n-1}\bar v_{n-1},
L001059	\end{equation}
L001060	using QPC \eqref{eq:QPC} together with \eqref{eq:E_close_GS}.
L001061	Here $v_n:=-\bra{\psi_n}V\ket{\psi_{n+1}}$ satisfies \begin{equation}\label{eq:vn<eps}
