L001063	\end{equation}
L001064	because only those $V_F$ can change $E_B$, and those checks act on $\le gL_B$ qudits.
L001065	
L001066	For $n=1$, \eqref{eq:An>} yields \begin{equation}
L001067	    A_1 \le \frac{2g\epsilon}{\Delta} A_2
L001068	\end{equation}
L001069	using \eqref{eq:vn<eps}. Assuming \begin{equation}\label{eq:iterate_n}
L001070	    A_{n-1} \le \frac{3g\epsilon}{\Delta} A_n
L001071	\end{equation}
L001072	holds (which indeed holds for $n=2$), \eqref{eq:An>} implies \begin{equation}\label{eq:An-An-1<}
