L001096	\subsection{Global quantum Peierls condition and its consequence}
L001097	
L001098	
L001099	\begin{defn}[Global quantum Peierls condition]\label{def:QPC_global}
L001100	    We say that Hamiltonian $H$ satisfies $(\Delta,\theta,L,q)$-global QPC, if it satisfies $(\Delta,\theta,L,q)$ QPC with the following extra conditions: \begin{enumerate}
L001101	        \item The different subspaces do not overlap $P_kP_{k'}=0$ ($k\neq k'$), and cannot be connected by $H$: \begin{equation}\label{eq:PkHPk=0}
L001102	            P_k H P_{k'}=0.
L001103	        \end{equation}
L001104	        Let $P_{\rm out}=I-\sum_{k=1}^K P_k$ project onto the subspace not included in any wells/bottlenecks.
L001105	        \item There exists a set $\mathcal{B}_{\rm out}$ of operators $B^2=B$, and a basis $\{\kpsi\}$ of subspace $P_{\rm out}$, such that for each basis $\kpsi$, there exists at least one $B\in \mathcal{B}_{\rm out}$ with $B\kpsi =\kpsi$.
L001106	        \item Like point 3 in Definition \ref{def:q_bottle}, each $B\in \mathcal{B}_{\rm out}$ corresponds to a set of checks and $B=1$ corresponds to those checks all being excited. Let operator $E_B$ count the number of excited checks in those checks belonging to $B$ (so $L_B:=\norm{E_B}$ is the number of checks), and $Q_{B,\ge n}$ projects onto the subspace for $E_B\ge n$. We require \begin{equation}\label{eq:QPC_global}
L001107	        \bra{\psi}H\kpsi \ge \Delta L_B + H_{\mathrm{min}},
L001108	    \end{equation}
L001109	    with $H_{\mathrm{min}}$ being the lowest eigenvalue of $H$,
L001110	    for any \begin{equation}\label{eq:Q>4/5L_B}
L001111	        Q_{B,\ge \frac{4}{5}L_B}\kpsi = \kpsi.
L001112	    \end{equation}
L001113	    \item $L_B\ge L$ for any $B\in \mathcal{B}_{\rm out}$. The number of $B$s in $\mathcal{B}_{\rm out}$ with $L_B=L'$ is smaller than or equal to $\ee^{\theta L'}$.
L001114	    \end{enumerate}
L001115	    When this criterion is applied to classical Hamiltonians $H$ (which are diagonal in the basis labeled by the classical configuration space $\Omega$) we can refer to it as a classical global Peierls condition.
L001116	
L001117	\end{defn}
L001118	
L001119	This global QPC condition constrains the whole Hilbert space rather than just $P_k$s in QPC, where the energy estimate \eqref{eq:QPC_global} holds for any state in the $E_B$ window, not just those contained in some $P_k$. Interestingly, the QPC condition Definition \ref{def:QPC} can be formulated with this stronger version of energy estimate, which is already sufficient to show structures of global eigenstates (rather than eigenstates constrained in subspace $P_k$):
L001120	
L001121	\begin{cor}\label{cor:Phipsi}
L001122	    Consider the same setting as Theorem \ref{thm:mainstable} where we further require \eqref{eq:QPC} to hold for any state \eqref{eq:Q>4/5L} not necessarily contained in $P_k$. Suppose $P_k$ commutes with all checks.\footnote{This holds trivially for classical models where the checks and $P_k$ are all classical operators.} The following holds for any eigenstate $H|\psi\rangle = E|\psi\rangle$ of the global Hamiltonian with\begin{equation}\label{eq:E<Hmin}
L001123	        E \le \frac{\Delta}{2}L+H_{\mathrm{min}}.
L001124	    \end{equation}
L001125	    \eqref{eq:Phik<expL} holds for any $k$.
L001126	    Moreover, for each well $W_k$,  $P_k|\psi\rangle$ is either a $\delta$-almost eigenstate of $H$ with \begin{equation}\label{eq:delta=}
