L001325	        \bra{\psi}H_0\kpsi = \sum_\bz \abs{a_\bz}^2 H_0(\bz) &\ge \sum_\bz \abs{a_\bz}^2 \mlr{\Delta L_B + H_0(\ell_A\cdot \bz)}
