L001396	\begin{prop}
L001397	    Let $A_{\alpha,i}$ be a collection of $(L_*/2)$-local Hermitian observables:   $i\in \tilde\Lambda \subseteq \Lambda$ denote vertices around which $A_{\alpha ,i}$ acts locally, while $\alpha$ is a vector index in a non-trivial irreducible representation $\mathcal{U}$ of $G$ such that \begin{equation}
L001398	        \ell^\dagger A_{\alpha ,i}\ell = \sum_\beta \mathcal{U}_{\alpha\beta}(\ell)A_{\beta,i}.
L001399	    \end{equation}
L001400	    If $|\tilde\Lambda|$ is proportional to $|\Lambda|$ with a constant prefactor, and a state $|\psi\rangle$ with $(R,\delta,L_*)$-SSB satisfies \begin{equation}
L001401	        \left|\sum_{i\in\tilde\Lambda}\langle \psi_k|A_{\alpha , i}|\psi_k\rangle \right| > c|\tilde\Lambda| \label{eq:longrangeorder0}
L001402	    \end{equation}
L001403	    for (at least) one well $\ket{\psi_k}=P_k\kpsi$ and at least one $\alpha$ where $c$ is not too small \begin{equation}\label{eq:c>delta2}
L001404	        c>2\sqrt{\delta+2\delta^2} \norm{A_{\alpha,i}},
L001405	    \end{equation}
L001406	    then $\kpsi$ has long-range order: \begin{equation}
L001407	        \frac{1}{|\tilde \Lambda|^2}\sum_{i,j\in\tilde\Lambda} \left[ \langle \psi|A_{\alpha,i }A_{\alpha,j}|\psi\rangle-\langle \psi|A_{\alpha,i }|\psi\rangle \langle \psi |A_{\alpha,j}|\psi\rangle \right]> \frac{1}{2} c^2.  \label{eq:longrangeorder}
L001408	    \end{equation}
L001409	\end{prop}
L001410	\begin{proof}
L001411	    By the definitions above,
L001412	    \begin{equation}\label{eq:|A|<}
L001413	      \sum_{i\in\tilde\Lambda} \langle \psi_{\ell \cdot k}|A_{\alpha ,i} |\psi_{\ell \cdot k}\rangle  = \sum_{i\in\tilde\Lambda}\langle \psi_k|\ell^\dagger A_{\alpha ,i}\ell |\psi_k\rangle = \sum_{i\in\tilde\Lambda}\sum_{\beta} \mathcal{U}_{\alpha\beta}(\ell) \langle \psi_k|A_{\beta,i}|\psi_k\rangle
L001414	    \end{equation}
L001415	    where $\ket{\psi_k}=P_k\kpsi$.  Moreover since $|\psi\rangle$ has $(R,\delta,L_*)$-SSB and $A_{\alpha,i}A_{\alpha,j}$ acts on at most $L_*$ qudits by assumption, we see that for any $k\in G/G^\prime$, \begin{align}
L001416	     \left| \sum_{i\in\tilde\Lambda}  \langle \psi| A_{\alpha,i} |\psi\rangle \right|  &\le 2\delta |\tilde \Lambda| \lVert A_{\alpha,i}\rVert + \frac{1}{|G/G^\prime|} \left| \sum_{\ell \in G}\sum_{i\in\tilde\Lambda} \langle \psi_{\ell \cdot k}|A_{\alpha ,i} |\psi_{\ell \cdot k}\rangle \right| \notag \\
L001417	     &\le 2\delta |\tilde \Lambda| \lVert A_{\alpha,i}\rVert +\frac{1}{|G/G^\prime|} \left| \sum_{\ell \in G}\sum_{i\in\tilde\Lambda} \sum_{\beta} \mathcal{U}_{\alpha\beta}(\ell) \langle \psi_{k}|A_{\beta,i}|\psi_{k}\rangle \right| = 2\delta |\tilde \Lambda| \lVert A_{\alpha,i}\rVert
L001418	    \end{align}
L001419	    where in the first line we peel off the part of $|\psi\rangle$ which is not trapped inside of the wells $P_k$, and in the second line we use the Great Orthogonality Theorem from representation theory: $\sum_{\ell \in G} \mathcal{U}_{\alpha\beta}(\ell)=0$ for any non-trivial irreducible representation $\mathcal{U}$.  At the same time, we do know that \begin{align}
