L001421	        &\ge -2\delta |\tilde \Lambda|^2 \lVert A_{\alpha, i}\rVert^2 +\sum_{k \in G/G'} \left\langle \psi_{ k} \left| \left(\sum_{i\in\tilde\Lambda} A_{\alpha,i}\right)^2 \right| \psi_{ k}\right\rangle \notag \\
L001422	        &\ge -2\delta |\tilde \Lambda|^2 \lVert A_{\alpha, i}\rVert^2 + \max_{k\in G/G^\prime} \left| \left\langle \psi_{ k} \left| \sum_{i\in\tilde\Lambda} A_{\alpha,i} \right| \psi_{ k}\right\rangle  \right|^2 \ge -2\delta |\tilde \Lambda|^2 \lVert A_{\alpha, i}\rVert^2 +c^2 |\tilde \Lambda|^2,
L001423	    \end{align}
L001424	    where in the second line we used the fact that the operator being summed over is a positive semidefinite Hermitian operator to remove the absolute value bars, and in the third line we used \eqref{eq:longrangeorder0}. Combining with \eqref{eq:|A|<} and \eqref{eq:c>delta2} we obtain \eqref{eq:longrangeorder}.
