L001438	\begin{prop}\label{prop:symbreak_field}
L001439	 Let $H$ be a Hamiltonian which obeys the assumptions of Corollary \ref{cor:SSB} and whose unique ground state $|\psi\rangle$ is symmetric under $G$ and exhibits $G\rightarrow G^\prime$ SSB given by \eqref{eq:SSBdef}; let $P_k|\psi\rangle =:|\psi_k\rangle$. Suppose the ground state degeneracy is not huge: \begin{equation}\label{eq:K<eL}
L001440	        K \le \ee^{c'_\zeta L}-1, \where c'_\zeta := \frac{1}{10qg}\log \frac{1}{\zeta}.
L001441	\end{equation} Let $A$ be an operator ``charged" under the symmetry group $G$, with the property that for some $k_* \in G/G^\prime$,\footnote{If no such operator exists then one may define the state $|\psi\rangle$ as having local quantum topological order \cite{QI_meet_QM}.  We are not aware of any model that has topological order as well as SSB of a global (0-form) symmetry, as we are studying in this paper.  We doubt this can exist.} \begin{equation}\label{eq:A_break_sym}
L001442	    \langle \psi_{k}|A|\psi_k\rangle_{k\ne k_*} \ge \widehat\epsilon + \langle \psi_{k_*}|A|\psi_{k_*}\rangle ,
L001443	\end{equation}
L001444	where $\norm{A}\le \widehat{c}\;\widehat{\epsilon}$ for some constant $\widehat{c}$. Furthermore, $\langle \psi_{k}|A|\psi_{k'}\rangle=0$ for any $k\neq k'$.
L001445	Then, for any $\eta>0$, the ground state $|\widehat{\psi}\rangle$ of the Hamiltonian $\widehat{H} := H + A$ obeys \begin{equation}\label{eq:>1-eta}
L001446	    \langle \widehat{\psi}|\psi_{k_*}\rangle > 1 - \eta
L001447	\end{equation}
L001448	so long as\begin{equation}\label{eq:Delta>eps>}
L001449	   \widehat{\Delta} \ge c_1  \widehat{\epsilon}\ge c_1^2 \norm{H} \ee^{-\frac{1}{4}c'_\zeta L}
L001450	\end{equation}
L001451	for some constant $c_1$ determined by $q,g,\zeta,\eta$,
L001452	where $\widehat{\Delta}$ is the spectral gap of $P_k HP_k$ (for any $k\in G/G^\prime$) between its ground state and first excited state, and $L$ is sufficiently large.
L001453	\end{prop}
