L001455	\begin{proof}
L001456	The energy $\widehat{E}$ of the new ground state is close to the unperturbed one: $\widehat{E}\le H_{\rm min}+\norm{A}\le  H_{\rm min}+\widehat{c}\;\widehat{\epsilon}$, so that \begin{equation}\label{eq:H_hatpsi}
L001457	    \bra{\widehat{\psi}}H\ket{\widehat{\psi}} = \widehat{E} - \bra{\widehat{\psi}}A\ket{\widehat{\psi}} \le H_{\rm min}+2\widehat{c}\;\widehat{\epsilon}.
L001458	\end{equation}
L001459	Let $Q_<$ project onto eigenstates of $H$ with energy $E\le H_{\rm min} + \sqrt{\widehat{\Delta}\widehat{\epsilon}}$.
L001460	From Markov inequality, \eqref{eq:H_hatpsi} implies \begin{equation}\label{eq:Q<}
L001461	    1-\bra{\widehat{\psi}}Q_<\ket{\widehat{\psi}} \le \frac{\bra{\widehat{\psi}}H\ket{\widehat{\psi}}-H_{\rm min}}{\sqrt{\widehat{\Delta}\widehat{\epsilon}}} \le 2\widehat{c}\sqrt{\frac{\widehat{\epsilon}}{\widehat{\Delta}}},
L001462	\end{equation}
L001463	i.e. $\widehat{\psi}$ is mainly supported in subspace $Q_<$.
L001464	
L001465	We then show that $Q_<$ basically only contains ground states of each $P_k H P_k$.
L001466	Following a strategy from \cite{MBL_LDPC24}, notice that given a $k$ and a global eigenstate $H|\phi\rangle = E_\phi|\phi\rangle $ with $\langle \phi|\phi\rangle = 1$,  \begin{equation}
L001467	        \norm{ P_k |\phi\rangle }\le \lVert (P_k H P_k-E_\phi)^{-1}\rVert  \cdot \lVert H\rVert \cdot \norm{ P_{\rm out} |\phi\rangle}. \label{eq:wellconcentrationbound}
L001468	    \end{equation}
L001469	\eqref{eq:wellconcentrationbound} follows immediately from the projected Schr\"odinger equation $(P_k H P_k + P_kHP_{\rm out})|\phi\rangle = E_\phi P_k|\phi\rangle $.   By Corollary \ref{cor:wells}, we see that $\lVert P_{\rm out}|\phi\rangle \rVert\le c_\zeta \ee^{-2c_\zeta' L}$, so this implies that \begin{equation}\label{eq:PHP_close_E}
L001470	    \lVert (P_k H P_k-E_\phi)^{-1}\rVert \ge \frac{\norm{P_k\ket{\phi}}}{c_\zeta \norm{H}} \ee^{2c_\zeta' L} \ge \frac{K^{-1/2}}{2c_\zeta \norm{H}} \ee^{2c_\zeta' L} \ge  \frac{1}{2c_\zeta \norm{H}} \ee^{\frac{3}{2}c_\zeta' L}
L001471	\end{equation}
L001472	where we have used $\sum_k \norm{P_k\ket{\phi}}^2 = 1-\norm{P_k\ket{\phi}}^2\ge 1/4$ for sufficiently large $L$, chosen the $k$ that maximizes $\norm{P_k\ket{\phi}}$, and used \eqref{eq:K<eL} in the end. \eqref{eq:PHP_close_E} implies $E_\phi$ is within $2c_\zeta\norm{H}\ee^{-\frac{3}{2}c_\zeta' L}$ distance to an eigenvalue of $P_k H P_k$. As a result, since each $P_k H P_k$ has gap $\widehat{\Delta}$ between the two lowest eigenstates, there is also a gap in the spectrum of $H$: For any $E_\phi\le H_{\rm min}+\sqrt{\widehat{\Delta}\widehat{\epsilon}}$, it is exponentially close to the well ground state energy: \begin{equation}\label{eq:Ephi-H<}
