L001478	    \norm{(P_k H P_k-E_\phi)Q_{k,>} P_k\ket{\phi}} &\le \norm{\ket{\chi}} + \norm{(H_{k,\mathrm{min}}-E_\phi)(I-Q_{k,>}) P_k\ket{\phi}} \nonumber\\
L001479	    &\le 4c_\zeta\norm{H}\ee^{-\frac{3}{2}c_\zeta' L},
L001480	\end{align}
L001481	where we have used \eqref{eq:chi<} and \eqref{eq:Ephi-H<}. So \begin{equation}
L001482	    \norm{Q_{k,>} P_k\ket{\phi}} \le \norm{Q_{k,>}(P_k H P_k-E_\phi)Q_{k,>}}^{-1} 4c_\zeta\norm{H}\ee^{-\frac{3}{2}c_\zeta' L} \le \frac{2}{\widehat{\Delta}}4c_\zeta\norm{H}\ee^{-\frac{3}{2}c_\zeta' L},
L001483	\end{equation}
L001484	because $E_\phi$ is at least $\frac{1}{2}\widehat{\Delta}$ far from the excited energies. The support of $\ket{\phi}$ outside $\mathrm{Span}(\ket{\psi_k})$ (denoted by projector $Q_>=P_{\rm out}+\sum_k Q_{k,>}$) is \begin{align}\label{eq:Q>phi}
L001485	    \norm{Q_>\ket{\phi}} \le \lr{\norm{P_{\rm out}\ket{\phi}}^2+\sum_k \norm{Q_> P_k\ket{\phi}}^2}^{1/2} \le \sqrt{K+1}\frac{2}{\widehat{\Delta}}4c_\zeta\norm{H}\ee^{-\frac{3}{2}c_\zeta' L} \le \frac{8}{\widehat{\Delta}}c_\zeta\norm{H}\ee^{-c_\zeta' L}
L001486	\end{align}
L001487	using \eqref{eq:K<eL}. Since $\sum_\phi \norm{(I-Q_>)\ket{\phi}}^2 \le \trace(I-Q_>)\le K$, and each $\norm{(I-Q_>)\ket{\phi}}\ge 1/2$ from \eqref{eq:Q>phi}, there are at most $2K$ eigenstates $\phi$ in range \eqref{eq:Ephi-H<}.
L001488	Furthermore, $Q_<\ket{\widehat{\psi}}$ is supported in those eigenstates, so \begin{equation}
L001489	    \norm{Q_>Q_<\ket{\widehat{\psi}}} \le \sqrt{2K} \max_\phi \norm{Q_>\ket{\phi}} \le \frac{8\sqrt{2}}{\widehat{\Delta}}c_\zeta\norm{H}\ee^{-\frac{1}{2}c_\zeta' L}
L001490	\end{equation}
L001491	using \eqref{eq:K<eL}.
