L001493	We now evaluate energy of $\ket{\widehat{\psi}}=\sum_k \alpha_k \ket{\psi_k}+ \cdots$ and consider variation in $\alpha_k$:
L001494	\begin{align}\label{eq:variation}
L001495	\bra{\widehat{\psi}}\widehat{H}\ket{\widehat{\psi}} &= \bra{\widehat{\psi}}  (I-Q_<)\widehat{H}(I-Q_<)\ket{\widehat{\psi}}+\bra{\widehat{\psi}}  Q_<\widehat{H}Q_<\ket{\widehat{\psi}}+ \epsilon_< \nonumber\\
