L001498	where \begin{align}
L001499	    |\epsilon_<| &\le 2\abs{\bra{\widehat{\psi}}  Q_<\widehat{H}(I-Q_<)\ket{\widehat{\psi}}} \le 2\norm{A}\norm{(I-Q_<)\ket{\widehat{\psi}}}\le 2\widehat{c}\,\widehat{\epsilon}\lr{2\widehat{c}\sqrt{\frac{\widehat{\epsilon}}{\widehat{\Delta}}}}^{1/2}
L001500	\end{align}
L001501	using \eqref{eq:Q<}, and \begin{equation}
L001502	    \abs{\epsilon_>}\le 2\abs{\sum_k\alpha_k^*\bra{\psi_k}\widehat{H}Q_>Q_<\ket{\widehat{\psi}}}\le 3\norm{H}\norm{Q_>Q_<\ket{\widehat{\psi}}} \le \frac{24\sqrt{2}}{\widehat{\Delta}}c_\zeta\norm{H}^2\ee^{-\frac{1}{2}c_\zeta' L}.
