L001625	\begin{thm}\label{thm:randomchecks}
L001626	    Consider the 2d Ising model $H_0$ in Proposition \ref{prop:peierls_Ising} where $J_{ij}$ are instead iid random variables drawn from a probability density function $f(J)$ with compact support in the domain $[-J_1,J_2]$.   Suppose that \begin{equation}
L001627	        \mathbb{P}[J_{ij} >\Delta^\prime ]=1-\prand \label{eq:biasrandom}
L001628	    \end{equation}
L001629	    and that the inequalities $0\le J_1<\Delta<\Delta^\prime <J_2$ hold.  Then if \begin{equation}\label{eq:randIsing_condition}
L001630	        \chi:=a\log \frac{a}{\prand}-a+\prand > \theta
L001631	    \end{equation}
L001632	    where \begin{equation}
L001633	        a:=\frac{4\Delta^\prime-5\Delta-J_2}{5(\Delta^\prime+J_1)}>\prand,
L001634	    \end{equation} $H_0$ has a $(\Delta,\theta,L,R)$-global QPC with \eqref{eq:H0z>L}, with very high probability at large $L=c_R L_0$ ($c_R$ is a constant determined by $R$ in Proposition \ref{prop:peierls_Ising}):\begin{equation} \label{eq:probQPCviolated}
L001635	    \mathbb{P}(\text{global QPC is violated}) \le \frac{\mathrm{e}^{-(\chi-\theta)L}}{1-\mathrm{e}^{-(\chi-\theta)}}.
L001636	\end{equation}
L001637	As a result, under small symmetric perturbations, $H_0+V$ has $\mathbb{Z}_2\rightarrow 0$ SSB at low energies as Corollary \ref{cor:SSB}.
L001638	\end{thm}
L001639	
L001640	Note that as long as $4\Delta'>J_2$, condition \eqref{eq:randIsing_condition} always holds with some constant $\Delta>0$ at sufficiently small $\prand$.
L001641	
