L001776	    \begin{align}
L001777	        T_x^\dagger A_{(x,y)}T_x &:= A_{(x+1,y)}, \\
L001778	         T_y^\dagger A_{(x,y)}T_y &:= A_{(x,y+1)},
L001779	    \end{align}
L001780	\end{subequations}
L001781	where $(x,y)\in\Lambda = \mathbb{Z}_{L_0}\times \mathbb{Z}_{L_0}$, we notice that we can build a $\mathbb{Z}_{L_0}\times \mathbb{Z}_{L_0}$ symmetry group for $H$ generated by $\ell_x$ and $\ell_y$, defined as
L001782	\begin{equation}
L001783	    \ell_{x,y} := T_{x,y} X_{\mathrm{tot}}.
L001784	\end{equation}
