L001829	\subsection{Metastability from quantum Peierls condition with finite $L$}
L001830	
L001831	Our results will rely on the locality of dynamics:
L001832	\begin{defn}\label{def:LRB}
L001833	    Consider a subset $B\subset \Lambda$ and $A=\{i\in \Lambda:\mathsf{d}(i,B)\le R_B\}$.
L001834	    We say Hamiltonian $H$ satisfies $(t_{\rm LR},\delta_{\rm LR})$-local-simulatability for the sets $A,B$, if the following holds: For any evolution time $|t|\le t_{\rm LR}$, any operator $\OO_B$ acting on $B$ is evolved approximately by $H_A$ that is sum of terms in $H$ supported inside $A$, with error \begin{equation}\label{eq:LRB}
L001835	        \norm{\ee^{\ii t H}\OO_B\ee^{-\ii t H} -\ee^{\ii t H_A}\OO_B\ee^{-\ii t H_A}} \le \delta_{\rm LR} \norm{\OO_B}.
L001836	    \end{equation}
L001837	\end{defn}
L001838	
L001839	\eqref{eq:LRB} can be viewed as a non-standard form of Lieb-Robinson bound.
L001840	See e.g. \cite{ourreview} for a review on Lieb-Robinson bounds and a proof of \eqref{eq:LRB} in strictly local systems where $t_{\rm LR}=R_B/(2v)$ for some constant $v$ and $\delta_{\rm LR}$ is exponentially small in $R_B$. The above more general form also applies to long-range interactions \cite{Tran_2019_polyLC,Kuwahara:2019rlw,Tran:2020xpc,Tran:2021ogo}.
L001841	
L001842	\begin{thm}[Metastability from local quantum Peierls condition] \label{thm:metastability}
L001843	    Consider Hamiltonian $H$ that satisfies $(t_{\rm LR},\delta_{\rm LR})$-local simulatability for the sets $A,B$ chosen in Definition \ref{def:LRB}. Suppose that $H_A$ obeys a $(\Delta,\theta,L,R)$-QPC with respect to a quantum bottleneck structure.  For any well $k$, let $\mathcal{P}^A_k$ be a projector (acting on $A$) onto $M$ eigenstates of $P_k H_AP_k$ with energy $E$ obeying \eqref{eq:E_close_GS}. Here the $M$ states can be arbitrarily chosen in the set of all such states. Then for any density matrix $\rho$ such that reduced density matrix $\rho_A$ obeys
L001844	    \begin{equation}\label{eq:mostlymetastable}
L001845	        \trace\left(\mathcal{P}^A_k \rho_A \right) > 1-\delta',
L001846	    \end{equation}
L001847	    for any operator $\mathcal{O}_B$ acting in $B$ that is normalized ($\norm{\OO_B}=1$), \begin{equation}\label{eq:metastable_PHP}
L001848	       \left| \trace\left(\rho \left( \mathrm{e}^{\mathrm{i}Ht}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}Ht} - \mathrm{e}^{\mathrm{i}P_kH_AP_kt}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}P_kH_AP_kt} \right)\right)  \right| \le 8|t|\sqrt{M}\delta + 4 \sqrt{\delta'} + \delta_{\rm LR},
L001849	    \end{equation}
L001850	    for all times $|t|\le t_{\rm LR}$. Here $\delta$ is given by \eqref{eq:provealmost} with $\norm{H}$ replaced by $\norm{H_A}$.
L001851	
L001852	    If furthermore $\mathcal{P}^A_k \OO_B\mathcal{P}^A_k\ge c_k > 0$, then \begin{equation}\label{eq:OB>ck}
L001853	        \trace\left(\rho  \mathrm{e}^{\mathrm{i}Ht}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}Ht}\right) \ge c_k(1-\delta') - 2 \sqrt{\delta'}-8|t|\sqrt{M}\delta - \delta_{\rm LR}
L001854	    \end{equation}
L001855	\end{thm}
L001856	
L001857	The key point of Theorem \ref{thm:metastability} is that even if we have a finite-sized notion of metastability on a fixed scale $L$, there are still important and observable consequences.   Local observables $\mathcal{O}_B$ will evolve as if the dynamics is restricted to within a bottleneck $k$ for timescales set by $R_B$ from Lieb-Robinson bound. In particular, if $\OO_B$ has signature in well $k$, that signature is preserved approximately up to time $t_{\rm LR}$.
L001858	
L001859	Although $R_B$ and $L$ are finite constants, we will show in an explicit example (Theorem \ref{thm:rand_metastab}) that that $R_B \sim \mathrm{e}^{L}$ is achievable in quantum Ising models.  This will establish the non-perturbatively slow decay of gapless false vacua obeying a QPC.
L001860	
L001861	\begin{proof}[Proof of Theorem \ref{thm:metastability}]  The local simulatability \eqref{eq:LRB} approximates the evolution by $H_A$: \begin{equation}\label{eq:<deltaLR}
L001862	       \left| \trace\left(\rho \mathrm{e}^{\mathrm{i}Ht}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}Ht}\right) - \trace\left(\mathrm{e}^{-\mathrm{i}H_At}\rho_A\mathrm{e}^{\mathrm{i}H_At}\mathcal{O}_B \right)  \right|=\left| \trace\left(\rho \left( \mathrm{e}^{\mathrm{i}Ht}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}Ht} - \mathrm{e}^{\mathrm{i}H_At}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}H_At} \right)\right)  \right| \le \delta_{\rm LR},
L001863	    \end{equation}
L001864	where we have evaluated $\trace(\rho\, \mathrm{e}^{\mathrm{i}H_A t}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}H_A t})=\trace(\mathrm{e}^{-\mathrm{i}H_A t}\rho_A \mathrm{e}^{\mathrm{i}H_A t}\mathcal{O}_B)$ by thinking of time-evolving $\rho_A$ rather than $\mathcal{O}_B$.   From \eqref{eq:mostlymetastable} and Theorem \ref{thm:mainstable}, we know that $\rho_A$ mostly consists of $\delta$-almost eigenstates of $H_A$ with $\delta$ given by \eqref{eq:provealmost}. Let $\rho_A(t):=\mathrm{e}^{-\mathrm{i}H_A t}\rho_A \mathrm{e}^{\mathrm{i}H_A t}, \widetilde{\rho}_A(t):=\mathrm{e}^{-\mathrm{i}H_A t}\mathcal{P}^A_k\rho_A \mathcal{P}^A_k \mathrm{e}^{\mathrm{i}H_A t}$, we have \begin{align}
L001865	    &\norm{\rho_A(t) -\widetilde{\rho}_A(t)}_1 = \norm{\rho_A -\widetilde{\rho}_A}_1 = \norm{(1-\mathcal{P}^A_k)\rho_A + \mathcal{P}^A_k\rho_A (1-\mathcal{P}^A_k)}_1 \nonumber\\
L001866	    &\qquad\le 2 \norm{(1-\mathcal{P}^A_k)\rho_A}_1 =  2 \norm{(1-\mathcal{P}^A_k)\sqrt{\rho_A}\cdot \sqrt{\rho_A}}_1 \hspace{30em}\mytag{\text{Triangle inequality and }\norm{\mathcal{P}^A_k\OO}_1\le \norm{\mathcal{P}^A_k}\norm{\OO}_1= \norm{\OO}_1}\\
L001867	    &\qquad\le 2 \norm{(1-\mathcal{P}^A_k)\sqrt{\rho_A}}_2 \norm{\sqrt{\rho_A}}_2 \mytag{\text{H\"{o}lder's inequality}} \\
L001868	    &\qquad= 2 \mlr{\trace\lr{(1-\mathcal{P}^A_k)\rho_A} \trace(\rho_A) }^{1/2} \le 2\sqrt{\delta'} \label{eq:rho-tilde}
L001869	\end{align}
L001870	using \eqref{eq:mostlymetastable}. Similarly, \begin{equation}\label{eq:-rho'}
L001871	    \norm{\mathrm{e}^{-\mathrm{i}P_kH_A P_kt}\rho_A \mathrm{e}^{\mathrm{i}P_kH_AP_k t}-\rho'_A(t)}_1\le 2 \sqrt{\delta'}
L001872	\end{equation}
L001873	where \begin{equation}
L001874	    \rho'_A(t):=\mathrm{e}^{-\mathrm{i}P_kH_A P_kt}\mathcal{P}^A_k\rho_A \mathcal{P}^A_k \mathrm{e}^{\mathrm{i}P_kH_AP_k t}=\mathrm{e}^{-\mathrm{i}\mathcal{P}^A_kH_A \mathcal{P}^A_kt}\mathcal{P}^A_k\rho_A \mathcal{P}^A_k \mathrm{e}^{\mathrm{i}\mathcal{P}^A_kH_A\mathcal{P}^A_k t}
L001875	\end{equation}
L001876	because $\mathcal{P}^A_k$ commutes with $P_k H_A P_k$.
L001877	
L001878	To compare $\widetilde{\rho}_A(t)$ with $\rho'_A(t)$,
L001879	we apply Duhamel identity $\ee^{t\mathcal{A}} = \ee^{t\mathcal{B}}+\int^t_0\dd t' \ee^{(t-t')\mathcal{A}} (\mathcal{A}-\mathcal{B})\ee^{t'\mathcal{B}}$: \begin{equation}\label{eq:duhamel}
L001880	    \widetilde{\rho}_A(t)-\rho'_A(t) = -\ii \int^t_0 \dd t' \ee^{-\ii (t-t') H_A}\mlr{H_A-\mathcal{P}^A_k H_A \mathcal{P}^A_k, \rho'_A(t')} \ee^{\ii (t-t') H_A}.
L001881	\end{equation}
L001882	Taking trace norm of \eqref{eq:duhamel} and using triangle inequality, we get \begin{align}
L001883	    \norm{\widetilde{\rho}_A(t)-\rho'_A(t)}_1 &\le \int^t_0 \dd t' \norm{ \mlr{H_A-\mathcal{P}^A_k H_A \mathcal{P}^A_k, \rho'_A(t')} }_1 \nonumber\\
L001884	    &=\int^t_0 \dd t' \norm{ \mlr{(1-\mathcal{P}^A_k) H_A \mathcal{P}^A_k +  \mathcal{P}^A_k H_A(1-\mathcal{P}^A_k),  \rho'_A(t')} }_1 \hspace{10em} \mytag{(1-\mathcal{P}^A_k)\rho'_A(t')=0} \\
L001885	    & \le 4 \int^t_0 \dd t' \norm{(1-\mathcal{P}^A_k) H_A \mathcal{P}^A_k} \norm{\rho'_A(t')}_1 \mytag{\text{Submultiplicativity}}\\
L001886	    & \le 4 \int^t_0 \dd t' \norm{(1-\mathcal{P}^A_k) [H_A, \mathcal{P}^A_k]}\cdot 1 \mytag{(1-\mathcal{P}^A_k)\mathcal{P}^A_k=0}\\
L001887	    &\le 4|t|\norm{[H_A,\mathcal{P}^A_k]}. \label{eq:tilde-rho'}
L001888	\end{align}
L001889	Let $(E_m,\psi_m)$ ($m=1,\cdots,M$) be the eigenstates of $P_kH_AP_k$ in $\mathcal{P}^A_k$:
L001890	\begin{align}
L001891	    \norm{[H_A,\mathcal{P}^A_k]}&= \norm{\sum_{m=1}^M \lr{\ket{r_m}\bra{\psi_m} - \ket{\psi_m}\bra{r_m}} } \mytag{\ket{r_m}:=(H_A-E_m)\ket{\psi_m}} \\
L001892	    &\le 2 \norm{\sum_{m=1}^M \ket{r_m}\bra{\psi_m}} \mytag{\text{Triangle inequality}}\\
L001893	    &\le 2 \lr{\sum_{m=1}^M \braket{r_m|r_m}}^{1/2} \mytag{\psi_m\text{ are orthogonal}}\\
L001894	    &\le 2\sqrt{M}\delta \label{eq:H_commute_P<}
L001895	\end{align}
L001896	from \eqref{eq:provealmost}.
L001897	
L001898	Combining \eqref{eq:rho-tilde}, \eqref{eq:-rho'}, \eqref{eq:tilde-rho'} and \eqref{eq:H_commute_P<} using triangle inequality, \begin{equation}
L001899	    \norm{\mathrm{e}^{-\mathrm{i}P_kH_A P_kt}\rho_A \mathrm{e}^{\mathrm{i}P_kH_AP_k t}-\rho_A(t)}_1 \le 8|t|\sqrt{M}\delta + 4 \sqrt{\delta'},
L001900	\end{equation}
L001901	which leads to \eqref{eq:metastable_PHP} using \eqref{eq:<deltaLR} and $\abs{\trace\lr{\OO \OO'}}\le \norm{\OO}\norm{\OO'}_1$.
L001902	
L001903	To show \eqref{eq:OB>ck}, we use the fact that \begin{equation}\label{eq:rho-rho'}
L001904	    \norm{\rho_A(t)-\rho'_A(t)}_1 \le 8|t|\sqrt{M}\delta + 2 \sqrt{\delta'}
L001905	\end{equation}
L001906	using \eqref{eq:rho-tilde}, \eqref{eq:tilde-rho'} and \eqref{eq:H_commute_P<}. Since $\rho'_A$ is supported in $\mathcal{P}^A_k$ in which $\OO_B\ge c_k$,  \begin{equation}\label{eq:OBrho'}
L001907	    \trace\lr{\OO_B \rho'_A(t)}\ge c_k \trace\lr{\rho'_A} = c_k \trace\lr{\mathcal{P}^A_k\rho} \ge c_k(1-\delta').
L001908	\end{equation}
L001909	Combining \eqref{eq:<deltaLR}, \eqref{eq:rho-rho'} and \eqref{eq:OBrho'} yields
L001910	\eqref{eq:OB>ck}.
L001911	\end{proof}
L001912	
L001913	We also remark that the result above allows us to apply our results to study local observables in a straightforward fashion, in systems in the strict thermodynamic limit, e.g. random bond Ising models where $\Lambda = \mathbb{Z}^d$.   One simply restricts to regions $A$ of arbitrarily large (but finite) size.
L001914	
L001915	\subsection{False vacuum decay in the random bond Ising model}
L001916	As an important application of the general framework for finite-size quantum bottlenecks discussed above, we now present a new proof that the false vacuum decays non-perturbatively slowly in the quantum Ising model.   This new proof will also apply to a gapless false vacuum, e.g. in the random bond Ising model, which is beyond the regime of validity of the formalism developed in \cite{metastable_localgap}.
L001917	
L001918	\begin{thm}\label{thm:rand_metastab}
L001919	    Consider the same random bond Ising model $H_0$ as Theorem \ref{thm:randomchecks} with constants $0\le J_1<\Delta'<J_2$. Under any $q$-local perturbation $V$ of local strength $\epsilon$ in \eqref{eq:eps=V}, for any constant $R>0$, $H=H_0+V$ satisfies $(\frac{\Delta}{2},\theta,c_1\frac{\Delta}{\epsilon},R)$ QPC if $\prand < \prand_{\rm c}, \epsilon < \epsilon_{\rm c}$ and \begin{equation}\label{eq:L0<exp}
L001920	        L_0\le \exp\lr{c_2\frac{\Delta}{\epsilon}}.
L001921	    \end{equation}
L001922	    Here $\Delta,\theta,\prand_{\rm c},\epsilon_{\rm c},c_1,c_2>0$ are constants determined by $J_1,J_2,\Delta',q,R$.
L001923	
L001924	    Furthermore, suppose $V$ is $2$d-local in the sense that each $F$ in \eqref{eq:eps=V} is connected in the 2d lattice. Even if \eqref{eq:L0<exp} does not hold, for any ball region $B$ of radius \begin{equation}\label{eq:r<}
L001925	        c_3\frac{\Delta}{\epsilon} \le r \le \exp\lr{c_2\frac{\Delta}{2\epsilon}}
L001926	    \end{equation}
L001927	    there exists a local observable $\OO_B$ with $\norm{\OO_B}=1$ supported in $B$ such that there are two initial states $\rho_\pm$ with \begin{equation}\label{eq:OB>1/2}
L001928	        \pm \trace\left(\rho_\pm  \mathrm{e}^{\mathrm{i}Ht}\mathcal{O}_B\mathrm{e}^{-\mathrm{i}Ht}\right) \ge \frac{1}{2}, \qquad \forall |t|\le \exp\lr{c_4\frac{\Delta}{\epsilon}}.
L001929	    \end{equation}
L001930	    Here $c_3,c_4$ are constants determined by $J_1,J_2,\Delta',q,R$.
L001931	\end{thm}
L001932	
L001933	\begin{proof}
L001934	We use the same bottleneck structure as Proposition \ref{prop:peierls_Ising} with one difference: The largest DW-loop size in the two wells $W_1,W_2$ is $L=c_1/\epsilon$ that depends on perturbation strength rather than the total system size. The number of bottleneck indicators is still $|\mathcal{B}|\le \ee^{\theta L}$ using \eqref{eq:|B|<} and \eqref{eq:L0<exp}, where constant $\theta$ is determined by $c_1,c_2,R$.
L001935	
L001936	From the proof of Theorem \ref{thm:randomchecks}, we know that as long as $\prand$ is sufficiently small ($<\prand_{\rm c}$ determined by $\theta,J_1,J_2,\Delta'$), $H_0$ satisfies \eqref{eq:H0z>L} for all bottleneck indicators with some constant $\Delta>0$. Following the proof of Theorem \ref{thm:symmetry_QPC}, it remains to show \begin{equation}\label{eq:V-V_metastab}
L001937	    \bra{\psi}\ell_A^\dagger V \ell_A -V\kpsi \le L_B \frac{\Delta}{2}
L001938	\end{equation}
L001939	in order to prove QPC for $H$ with a slightly smaller $\frac{\Delta}{2}$ parameter. \eqref{eq:V-V_metastab} holds because \begin{align}
L001940	    \bra{\psi}\ell_A^\dagger V \ell_A -V\kpsi &\le \norm{\ell_A^\dagger V \ell_A -V}\nonumber\\
L001941	    &= \norm{\sum_{F:F\cap A\neq \emptyset} \ell_A^\dagger V_F \ell_A -V_F} \mytag{\ell_A\text{ acts inside }A}\\
L001942	    &\le \sum_{i\in A}\sum_{F\ni i} \norm{\ell_A^\dagger V_F \ell_A -V_F} \mytag{\text{Triangle inequality}}\\
L001943	    &\le \sum_{i\in A}\sum_{F\ni i} 2\norm{V_F}\le 2|A|\epsilon \nonumber\\
L001944	    &\le 2c_3 L_B^2 \epsilon \le L_B \frac{\Delta}{2}.
L001945	\end{align}
L001946	Here in the last line, we have used the fact that a $L_B$-size loop encircles an area bounded by $|A|\le c_3 L_B^2$ for some constant $c_3$, and that $L_B \epsilon\le 4RL\epsilon=4Rc_1$ is chosen to be a sufficiently small constant. We have thus proven $(\frac{\Delta}{2},\theta,c_1\frac{\Delta}{\epsilon},R)$ QPC for $H$.
L001947	
L001948	We then apply Theorem \ref{thm:metastability} to show the second part of the claim.
L001949	
L001950	First, there exists an observable $\OO_B$ with $\norm{\OO_B}=1$ such that \begin{equation}\label{eq:OB_P1P2}
L001951	    P_1 \OO_B P_1 \ge \frac{2}{3}> -\frac{2}{3} \ge P_2 \OO_B P_2.
L001952	\end{equation}
L001953	The reason is that with a sufficiently large constant $c_3$, $r\gg L$ so that we can tell which region is the connected sea of $0$s solely from region $B$ for any bitstring in $P_1$: If a DW is only partially contained in $B$, it separates $B$ into regions and we know there is a single largest region which is its outside. One can therefore define a observable $\OO_B$ diagonal in the $z$-basis to tell the bit value in the connected sea, which returns $\pm 1$ for the two wells and satisfies \eqref{eq:OB_P1P2}.
L001954	
L001955	We then choose region $A$ to be a $L_0'\times L_0'$ box enclosing $B$ with \begin{equation}
L001956	    R_B= \frac{1}{2}\exp\lr{c_2\frac{\Delta}{\epsilon}} - r -1
L001957	\end{equation}
L001958	so that $L_0'$ satisfies \eqref{eq:L0<exp}. Note that $R_B>0$ for sufficiently small $\epsilon_{\rm c}$ due to the upper bound of $r$ \eqref{eq:r<}. Furthermore, the QPC condition implies $\delta$-almost eigenstates with \begin{align}\label{eq:delta<c4}
L001959	    \delta &\le c_5(L_0')^2 \exp\mlr{-c_6 L\log \frac{\epsilon_{\rm c}'}{\epsilon}} \nonumber\\
L001960	    &\le c_5 \exp\lr{2c_2\frac{\Delta}{\epsilon}} \exp\mlr{-c_6 c_1 \frac{\Delta}{\epsilon}\log \frac{\epsilon_{\rm c}'}{\epsilon} } \nonumber\\
L001961	    &\le \exp\lr{-c_4'\frac{\Delta}{\epsilon}}
L001962	\end{align}
L001963	from \eqref{eq:provealmost}, where $c_4',c_5,c_6,\epsilon_{\rm c}'>0$ are constants and we have chosen $\epsilon_{\rm c} = \frac{1}{2}\epsilon_{\rm c}^\prime$ to be sufficiently small.
L001964	
L001965	
L001966	Since $V$ is $2$d-local, $H$ satisfies a Lieb-Robinson bound with a finite velocity and exponential-decaying tails, and therefore $(c_{\rm LR}R_B,0.1)$-local simulatability for some constant $c_{\rm LR}$ \cite{ourreview}.
L001967	
L001968	We then choose $\rho_\pm $ to be the lowest eigenstate of $P_1 H_A P_1$ ($P_2 H_A P_2$), tensored with arbitrary state outside of $A$. Note that the corresponding energies $E$ obey \eqref{eq:E_close_GS} because it is just $E_{k,\mathrm{min}}$. \eqref{eq:OB>ck} then implies \eqref{eq:OB>1/2} with a sufficiently small $\epsilon_{\rm c}$ using $c_k=\frac{2}{3}, \delta'=0,M=1,\delta_{\rm LR}=0.1$, \eqref{eq:delta<c4} and a sufficiently small constant $c_4>0$ so that $|t|\le c_{\rm LR}R_B$ and $|t|\delta$ is exponentially small in $\Delta/\epsilon$.
L001969	\end{proof}
L001970	
L001971	Theorem \ref{thm:rand_metastab} will generalize in a straightforward way to $d$ dimensions with a $\exp\mlr{c\lr{\frac{\Delta}{\epsilon}}^{d-1}}$ lifetime for the false vacuum, although we have not gone into details of the Peierls conditions for higher-dimensional models in this paper.  It would be interesting if our methods could be modified to prove a tight $\exp\mlr{c\lr{\frac{\Delta}{\epsilon}}^{d}}$ lifetime that matches false vacuum decay in non-random Ising models \cite{metastable_localgap}.
L001972	
